pub fn two_sum(nums: &Vec<u32>, target: u32) -> (usize, usize) {
    let n = nums.len();
    assert!(n >= 2);

    // Brute force in lexicographic order (p ascending, then q ascending).
    // The first match is guaranteed to be the lexicographically smallest.
    for p in 0..n - 1 {
        for q in (p + 1)..n {
            // Assumption in the problem ensures nums[p] + nums[q] < 256 for all p != q,
            // so addition cannot overflow u32; still, u32 addition is safe here anyway.
            if nums[p] + nums[q] == target {
                return (p, q);
            }
        }
    }

    // Problem statement guarantees at least one solution exists.
    unreachable!("No pair sums to target, despite the problem's assumption");
}